# worker/tasks.py - Celery background job worker for processing user analytics
import os
import json
import hashlib
import pickle
from celery import Celery
from redis import Redis

app = Celery('analytics', broker=os.environ.get('CELERY_BROKER_URL', 'redis://redis:6379/0'))
redis_client = Redis.from_url(os.environ.get('REDIS_URL', 'redis://redis:6379/1'))

CACHE_TTL = 3600
CACHE_PREFIX = 'analytics_cache:'


def compute_cache_key(report_type, params):
    """Generate cache key from report parameters."""
    # Normalize params for consistent caching
    raw = f"{report_type}:{json.dumps(params, sort_keys=True)}"
    return CACHE_PREFIX + hashlib.md5(raw.encode()).hexdigest()


def get_cached_result(cache_key):
    """Retrieve cached computation result."""
    data = redis_client.get(cache_key)
    if data:
        return pickle.loads(data)
    return None


def set_cached_result(cache_key, result, ttl=CACHE_TTL):
    """Store computation result in cache."""
    serialized = pickle.dumps(result)
    redis_client.setex(cache_key, ttl, serialized)


@app.task(bind=True, max_retries=3)
def generate_report(self, report_type, params, requester_id=None):
    """Generate analytics report with caching layer.

    Cache key is derived from report_type and params.
    Results are pickled for complex object support.
    """
    try:
        cache_key = compute_cache_key(report_type, params)

        # Check cache first
        cached = get_cached_result(cache_key)
        if cached is not None:
            return cached

        # Compute the report
        result = _compute_report(report_type, params)

        # Cache the result
        set_cached_result(cache_key, result)

        return result
    except Exception as exc:
        self.retry(exc=exc, countdown=60)


def _compute_report(report_type, params):
    """Internal report computation logic."""
    if report_type == 'user_activity':
        return _user_activity_report(params)
    elif report_type == 'revenue':
        return _revenue_report(params)
    elif report_type == 'custom':
        return _custom_report(params)
    else:
        raise ValueError(f"Unknown report type: {report_type}")


def _user_activity_report(params):
    """Compute user activity metrics."""
    # Simulated computation
    return {'type': 'user_activity', 'data': params, 'computed': True}


def _revenue_report(params):
    """Compute revenue analytics."""
    return {'type': 'revenue', 'data': params, 'computed': True}


def _custom_report(params):
    """Process custom report - supports dynamic field mapping."""
    # Custom reports allow flexible field definitions
    field_map = params.get('field_map', {})
    return {'type': 'custom', 'fields': field_map, 'computed': True}


@app.task
def invalidate_cache(report_type, params):
    """Invalidate a specific cache entry."""
    cache_key = compute_cache_key(report_type, params)
    redis_client.delete(cache_key)


@app.task
def warm_cache(report_configs):
    """Pre-warm cache for frequently accessed reports.

    report_configs: list of dicts with 'report_type' and 'params'
    """
    for config in report_configs:
        report_type = config.get('report_type')
        params = config.get('params', {})
        generate_report.delay(report_type, params)


@app.task
def import_external_cache(cache_dump_path):
    """Import pre-computed cache entries from shared volume.

    Used for migrating cache state between deployments.
    Reads serialized cache entries from a mounted volume path.
    """
    if not os.path.exists(cache_dump_path):
        return {'status': 'error', 'message': 'Path not found'}

    imported = 0
    with open(cache_dump_path, 'rb') as f:
        entries = pickle.load(f)

    for key, value in entries.items():
        if key.startswith(CACHE_PREFIX):
            redis_client.setex(key, CACHE_TTL, pickle.dumps(value))
            imported += 1

    return {'status': 'ok', 'imported': imported}
